    pub const FIELD_NODE_ID: FieldId = FieldId::new(0x4);
    pub const FIELD_ROOT_PUBLIC_KEY: FieldId = FieldId::new(0x1);
    pub const FIELD_VENDOR_ID: FieldId = FieldId::new(0x2);

    #[must_use]
    pub fn new(
        root_public_key: impl Into<crate::Bytes>,
        vendor_id: impl Into<VendorId>,
        fabric_id: impl Into<FabricId>,
        node_id: impl Into<NodeId>,
        label: impl Into<String>,
    ) -> Self {
        Self {
            root_public_key: root_public_key.into(),
            vendor_id: vendor_id.into(),
            fabric_id: fabric_id.into(),
            node_id: node_id.into(),
            label: label.into(),
        }
    }

    pub(crate) fn decode_fields_inner(
        fields: Vec<(FieldId, AttributeValue)>,
    ) -> Result<Self, (Option<FieldId>, MatterStatus)> {
        let mut root_public_key = None;
        let mut vendor_id = None;
        let mut fabric_id = None;
        let mut node_id = None;
        let mut label = None;
        for (fid, fval) in fields {
            match fid.raw() {
                1 => {
                    if root_public_key.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <crate::Bytes>::try_from(fval)?;
                        (decoded.len() <= 65)
                            .then_some(())
                            .ok_or(MatterStatus::ConstraintError)?;
                        root_public_key = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                2 => {
                    if vendor_id.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <VendorId>::try_from(fval)?;
                        vendor_id = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                3 => {
                    if fabric_id.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <FabricId>::try_from(fval)?;
                        fabric_id = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                4 => {
                    if node_id.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <NodeId>::try_from(fval)?;
                        node_id = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                5 => {
                    if label.is_some() {
                        return Err((Some(fid), MatterStatus::ConstraintError));
                    }
                    let decode_one = || -> Result<(), MatterStatus> {
                        let decoded = <String>::try_from(fval)?;
                        (decoded.len() <= 32)
                            .then_some(())
                            .ok_or(MatterStatus::ConstraintError)?;
                        label = Some(decoded);
                        Ok(())
                    };
                    decode_one().map_err(|st| (Some(fid), st))?;
                }
                _ => return Err((Some(fid), MatterStatus::ConstraintError)),
            }
        }
        Ok(Self {
            root_public_key: root_public_key.ok_or((Some(FieldId::new(1)), MatterStatus::ConstraintError))?,
            vendor_id: vendor_id.ok_or((Some(FieldId::new(2)), MatterStatus::ConstraintError))?,
            fabric_id: fabric_id.ok_or((Some(FieldId::new(3)), MatterStatus::ConstraintError))?,
            node_id: node_id.ok_or((Some(FieldId::new(4)), MatterStatus::ConstraintError))?,
            label: label.ok_or((Some(FieldId::new(5)), MatterStatus::ConstraintError))?,
        })
    }

    pub(crate) fn encode_fields_inner(self) -> Vec<(FieldId, AttributeValue)> {
        alloc::vec![
            (Self::FIELD_ROOT_PUBLIC_KEY, AttributeValue::from(self.root_public_key)),
            (Self::FIELD_VENDOR_ID, AttributeValue::from(self.vendor_id)),
            (Self::FIELD_FABRIC_ID, AttributeValue::from(self.fabric_id)),
            (Self::FIELD_NODE_ID, AttributeValue::from(self.node_id)),
            (Self::FIELD_LABEL, AttributeValue::from(self.label)),
        ]
    }
